1	// Formatting filters for units, dates and long texts.
2	angular.module("castra.core")
3	    .filter("rationUnit", function () {
4	        return function (value, unit) {
5	            return (Number(value) || 0).toFixed(1) + " " + unit;
6	        };
7	    })
8	    .filter("shortDate", function () {
9	        return function (value) {
10	            return value ? new Date(value).toLocaleDateString() : "";
11	        };
12	    })
13	    .filter("truncate", function () {
