// A single tent with the number of beds taken.
angular.module("castra.core")
    .component("tentInspector", {
        templateUrl: "app/ajs/features/patrols/components/tent-inspector.html",
        controller: TentInspectorController,
        bindings: { tent: "<" }
    });

TentInspectorController.$inject = [ "patrolService" ];

function TentInspectorController (patrolService) {
    var $ctrl = this;

    $ctrl.$onInit = function () {
        $ctrl.tent = $ctrl.tent || patrolService.firstTent();
    };
}

